What is the output of the following C++ program?
#include <iostream>
using namespace std;

int main()
{
 if(-10)
{
 cout<<"Welcome";
}
else
{
 cout<<"Good Bye";
}
return 0;
}

What is the output of the following code?
#include <iostream>
using namespace std;
void compute(int *x, int *y)
{
 *x=*x+*y;
 *y=*x * *y;
 cout<<*x<<" "<<*y<<endl;
}

int main(){
 int a=10,b=5;
 compute(&a, &b);
 cout<<a<<" "<<b;
}

What is the output of the following C++ program?
#include <iostream>
using namespace std;
int main() {
int a = 10, b = 20;
int c = (a > b) ? a++ : ++b;
cout << a << " " << b << " " << c;
return 0;
}

What will be the output of the following code?
int arr[] = {10, 20, 30, 40, 50};
int *ptr = arr + 2;
cout << *ptr << " " << *(ptr + 1);

Examine the following class definition:
class Account {
    private double balance;
}
From a software engineering perspective, why is declaring balance as private considered good design practice?

